import java.util.*;
import java.io.*;

public class Main {
    static long[] blockFollowers(long[] ids, long[] p, long[] q, long a, long b) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] ids = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); ids[i] = (long) in.nval; }
        in.nextToken();
        int e = (int) in.nval;
        long[] p = new long[e], q = new long[e];
        for (int i = 0; i < e; i++) {
            in.nextToken(); p[i] = (long) in.nval;
            in.nextToken(); q[i] = (long) in.nval;
        }
        in.nextToken();
        long a = (long) in.nval;
        in.nextToken();
        long b = (long) in.nval;
        long[] res = blockFollowers(ids, p, q, a, b);
        StringBuilder sb = new StringBuilder();
        sb.append(res.length);
        for (long x : res) sb.append(' ').append(x);
        System.out.println(sb);
    }
}
